    }

    public class RoutingContext : IRoutingContext
    {
        public string PrimaryKey { get; }
        public IReadOnlyDictionary<string, string> Tags { get; }
        public object? Payload { get; }

        public RoutingContext(string primaryKey, IReadOnlyDictionary<string, string>? tags = null, object? payload = null)
        {
            PrimaryKey = primaryKey ?? throw new ArgumentNullException(nameof(primaryKey));
            Tags = tags ?? new Dictionary<string, string>();
            Payload = payload;
        }

        public T? GetValue<T>(string path)
        {
            if (string.IsNullOrEmpty(path))
                return default;

            var segments = path.Split('.');
            object? current = this;

            foreach (var segment in segments)
            {
                if (current == null) return default;

                var type = current.GetType();
                var prop = type.GetProperty(segment, BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase);
                if (prop != null)
                {
                    current = prop.GetValue(current);
                    continue;
                }

                var field = type.GetField(segment, BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase);
                if (field != null)
                {
                    current = field.GetValue(current);
                    continue;
                }

                if (current is IDictionary<string, object> dict && dict.TryGetValue(segment, out var dictValue))
                {
                    current = dictValue;
                    continue;
                }

                if (current is IReadOnlyDictionary<string, string> rd && rd.TryGetValue(segment, out var rdValue))
                {
                    current = rdValue;
                    continue;
                }

                return default;
            }

            if (current is T typed) return typed;
            try
            {
                return (T?)Convert.ChangeType(current, typeof(T));
            }
            catch
            {
                return default;
            }
        }
    }

