    public class ExpressionRule : IRelationshipRule
    {
        private readonly Func<IRoutingContext, bool> _compiledPredicate;

        public string Id { get; }
        public int Priority { get; }
        public string Condition { get; }
        public string TargetId { get; }
        public IReadOnlyDictionary<string, string> TargetParameters { get; }

        public ExpressionRule(string id, int priority, string condition, string targetId,
                            IReadOnlyDictionary<string, string>? parameters = null)
        {
            Id = id ?? throw new ArgumentNullException(nameof(id));
            Priority = priority;
            Condition = condition ?? throw new ArgumentNullException(nameof(condition));
            TargetId = targetId ?? throw new ArgumentNullException(nameof(targetId));
            TargetParameters = parameters ?? new Dictionary<string, string>();

            _compiledPredicate = CompileCondition(condition);
        }

        public bool Evaluate(IRoutingContext context) => _compiledPredicate(context);

        private static Func<IRoutingContext, bool> CompileCondition(string expression)
        {
            var contextParam = Expression.Parameter(typeof(IRoutingContext), "context");
            var parser = new ConditionParser(contextParam);
            var body = parser.Parse(expression);
            return Expression.Lambda<Func<IRoutingContext, bool>>(body, contextParam).Compile();
        }

        private class ConditionParser
        {
            private readonly ParameterExpression _contextParam;
            private string _expression = string.Empty;
            private int _index;

            public ConditionParser(ParameterExpression contextParam) => _contextParam = contextParam;

            public Expression Parse(string expression)
            {
                _expression = expression;
                _index = 0;
                return ParseOr();
            }

            private Expression ParseOr()
            {
                var left = ParseAnd();
                while (true)
                {
                    SkipWhitespace();
                    if (Peek(2) == "||")
                    {
                        Consume(2);
                        left = Expression.OrElse(left, ParseAnd());
                    }
                    else break;
                }
                return left;
            }

            private Expression ParseAnd()
            {
                var left = ParsePrimary();
                while (true)
                {
                    SkipWhitespace();
                    if (Peek(2) == "&&")
                    {
                        Consume(2);
                        left = Expression.AndAlso(left, ParsePrimary());
                    }
                    else break;
                }
                return left;
            }

            private Expression ParsePrimary()
            {
                SkipWhitespace();
                if (Peek(1) == "(")
                {
                    Consume(1);
                    var expr = ParseOr();
                    SkipWhitespace();
                    if (Peek(1) != ")") throw new FormatException("缺少右括号");
                    Consume(1);
                    return expr;
                }
                else if (Peek(1) == "!")
                {
                    Consume(1);
                    return Expression.Not(ParsePrimary());
                }
                else
                {
                    return ParseComparison();
                }
            }

            private Expression ParseComparison()
            {
                var left = ParseValue();
                SkipWhitespace();
                var op = ReadOperator();
                SkipWhitespace();
                var right = ParseValue();

                if (left.Type != right.Type)
                {
                    if (IsNumericType(left.Type) && IsNumericType(right.Type))
                    {
                        left = Expression.Convert(left, typeof(double));
                        right = Expression.Convert(right, typeof(double));
                    }
                    else
                    {
                        left = Expression.Convert(left, typeof(object));
                        right = Expression.Convert(right, typeof(object));
                    }
                }

                return op switch
                {
                    "==" => Expression.Equal(left, right),
                    "!=" => Expression.NotEqual(left, right),
                    ">" => Expression.GreaterThan(left, right),
                    ">=" => Expression.GreaterThanOrEqual(left, right),
                    "<" => Expression.LessThan(left, right),
                    "<=" => Expression.LessThanOrEqual(left, right),
                    _ => throw new NotSupportedException($"不支持的操作符: {op}")
                };
            }

            private static bool IsNumericType(Type type) =>
                type == typeof(int) || type == typeof(long) || type == typeof(double) || type == typeof(float) ||
                type == typeof(decimal) || type == typeof(byte) || type == typeof(short);

            private Expression ParseValue()
            {
                SkipWhitespace();
                if (char.IsDigit(_expression[_index]) || (_expression[_index] == '-' && _index + 1 < _expression.Length && char.IsDigit(_expression[_index + 1])))
                {
                    var start = _index;
                    while (_index < _expression.Length && (char.IsDigit(_expression[_index]) || _expression[_index] == '.' || _expression[_index] == '-'))
                        _index++;
                    var numStr = _expression.Substring(start, _index - start);
                    return numStr.Contains('.') ? Expression.Constant(double.Parse(numStr)) : Expression.Constant(int.Parse(numStr));
                }
                else if (_expression[_index] == '"')
                {
                    _index++;
                    var start = _index;
                    while (_index < _expression.Length && _expression[_index] != '"')
                    {
                        if (_expression[_index] == '\\' && _index + 1 < _expression.Length) _index++;
                        _index++;
                    }
                    var str = _expression.Substring(start, _index - start).Replace("\\\"", "\"").Replace("\\\\", "\\");
                    _index++;
                    return Expression.Constant(str);
                }
                else if (_expression[_index] == '\'')
                {
                    _index++;
                    var start = _index;
                    while (_index < _expression.Length && _expression[_index] != '\'')
                    {
                        if (_expression[_index] == '\\' && _index + 1 < _expression.Length) _index++;
                        _index++;
                    }
                    var str = _expression.Substring(start, _index - start).Replace("\\'", "'").Replace("\\\\", "\\");
                    _index++;
                    return Expression.Constant(str);
                }
                else if (Peek(4) == "true" && !char.IsLetterOrDigit(_expression[_index + 4]))
                {
                    Consume(4);
                    return Expression.Constant(true);
                }
                else if (Peek(5) == "false" && !char.IsLetterOrDigit(_expression[_index + 5]))
                {
                    Consume(5);
                    return Expression.Constant(false);
                }
                else if (Peek(4) == "null" && !char.IsLetterOrDigit(_expression[_index + 4]))
                {
                    Consume(4);
                    return Expression.Constant(null, typeof(object));
                }
                else
                {
                    return ParseVariable();
                }
            }

            private Expression ParseVariable()
            {
                var start = _index;
                while (_index < _expression.Length && (char.IsLetterOrDigit(_expression[_index]) || _expression[_index] == '_' || _expression[_index] == '.'))
                    _index++;
                var identifier = _expression.Substring(start, _index - start);

                if (identifier.StartsWith("Tags"))
                {
                    SkipWhitespace();
                    if (_index < _expression.Length && _expression[_index] == '[')
                    {
                        _index++;
                        SkipWhitespace();
                        char quote = _expression[_index];
                        if (quote != '"' && quote != '\'') throw new FormatException("Tags 索引器需要字符串键");
                        _index++;
                        var keyStart = _index;
                        while (_index < _expression.Length && _expression[_index] != quote)
                        {
                            if (_expression[_index] == '\\' && _index + 1 < _expression.Length) _index++;
                            _index++;
                        }
                        var key = _expression.Substring(keyStart, _index - keyStart);
                        _index++;
                        SkipWhitespace();
                        if (_index >= _expression.Length || _expression[_index] != ']') throw new FormatException("缺少 ]");
                        _index++;

                        var tagsProp = Expression.Property(_contextParam, nameof(IRoutingContext.Tags));
                        var indexer = tagsProp.Type.GetProperty("Item")!;
                        return Expression.MakeIndex(tagsProp, indexer, new[] { Expression.Constant(key) });
                    }
                    else
                    {
                        return Expression.Property(_contextParam, nameof(IRoutingContext.Tags));
                    }
                }
                else if (identifier == "PrimaryKey")
                {
                    return Expression.Property(_contextParam, nameof(IRoutingContext.PrimaryKey));
                }
                else if (identifier.StartsWith("Payload"))
                {
                    var payloadProp = Expression.Property(_contextParam, nameof(IRoutingContext.Payload));
                    var path = identifier.Substring("Payload".Length).TrimStart('.');
                    if (string.IsNullOrEmpty(path)) return payloadProp;
                    Expression expr = payloadProp;
                    foreach (var part in path.Split('.'))
                    {
                        if (string.IsNullOrEmpty(part)) continue;
                        expr = Expression.PropertyOrField(expr, part);
                    }
                    return expr;
                }
                else
                {
                    throw new FormatException($"未知的标识符: {identifier}");
                }
            }

            private string ReadOperator()
            {
                if (Peek(2) is "==" or "!=" or ">=" or "<=")
                {
                    var op = _expression.Substring(_index, 2);
                    _index += 2;
                    return op;
                }
                else if (Peek(1) is ">" or "<")
                {
                    var op = _expression.Substring(_index, 1);
                    _index += 1;
                    return op;
                }
                throw new FormatException("期望操作符");
            }

            private string Peek(int length) =>
                _index + length <= _expression.Length ? _expression.Substring(_index, length) : string.Empty;

            private void Consume(int count) => _index += count;

            private void SkipWhitespace()
            {
                while (_index < _expression.Length && char.IsWhiteSpace(_expression[_index]))
                    _index++;
            }
        }
    }

