    #region 规则集

    public interface IRuleSet
    {
        IEnumerable<IRelationshipRule> GetRules();
        void AddOrUpdateRule(IRelationshipRule rule);
        bool RemoveRule(string ruleId);
        void Clear();
    }

    public class InMemoryRuleSet : IRuleSet
    {
        private readonly ConcurrentDictionary<string, IRelationshipRule> _rules = new();

        public IEnumerable<IRelationshipRule> GetRules() =>
            _rules.Values.OrderByDescending(r => r.Priority);

        public void AddOrUpdateRule(IRelationshipRule rule) =>
            _rules.AddOrUpdate(rule.Id, rule, (_, _) => rule);

        public bool RemoveRule(string ruleId) => _rules.TryRemove(ruleId, out _);

        public void Clear() => _rules.Clear();
    }

    #endregion

    #region 匹配策略

    public interface IMatchingStrategy
    {
        IRelationshipRule? Match(IRoutingContext context, IRuleSet ruleSet);
        IEnumerable<IRelationshipRule> MatchAll(IRoutingContext context, IRuleSet ruleSet);
    }

    public class BestMatchStrategy : IMatchingStrategy
    {
        public IRelationshipRule? Match(IRoutingContext context, IRuleSet ruleSet) =>
            ruleSet.GetRules().FirstOrDefault(r => r.Evaluate(context));

        public IEnumerable<IRelationshipRule> MatchAll(IRoutingContext context, IRuleSet ruleSet) =>
            ruleSet.GetRules().Where(r => r.Evaluate(context));
    }

