    #region 目标解析器

    public interface ITargetResolver<TTarget>
    {
        TTarget Resolve(string targetId);
        bool TryResolve(string targetId, out TTarget? target);
    }

    public class DelegateTargetResolver<TTarget> : ITargetResolver<TTarget>
    {
        private readonly ConcurrentDictionary<string, TTarget> _registry = new();

        public void Register(string targetId, TTarget target) => _registry[targetId] = target;

        public bool Unregister(string targetId) => _registry.TryRemove(targetId, out _);

        public TTarget Resolve(string targetId)
        {
            if (_registry.TryGetValue(targetId, out var target)) return target;
            throw new KeyNotFoundException($"未注册的目标: {targetId}");
        }

        public bool TryResolve(string targetId, out TTarget? target) =>
            _registry.TryGetValue(targetId, out target);
    }

